rounds.styleCss:
/* fixture stylesheet: deliberately simple, passes every tier-2 check */
:root { color-scheme: light; }
html { font: 16px/1.5 system-ui, sans-serif; color: #1a1a1a; background: #fafaf7; }
body { margin: 0 auto; max-width: 48rem; padding: 0 1rem; }
header { display: flex; gap: 1rem; align-items: baseline; padding: 1rem 0; border-bottom: 2px solid #1a1a1a; }
header > a { font-weight: 700; color: #1a1a1a; text-decoration: none; }
nav a { color: #444; margin-right: .5rem; }
h1 { font-size: 1.5rem; }
a { color: #0b4f9c; }
ol.stories { padding-left: 2rem; }
ol.stories li { margin: .75rem 0; }
.title { font-size: 1.1rem; overflow-wrap: anywhere; }
.domain { color: #555; font-size: .9rem; }
.meta { color: #555; font-size: .85rem; margin: .1rem 0 0; }
.meta a { color: #555; }
ul.comments { list-style: none; padding-left: 0; }
ul.comments ul.comments { padding-left: 1rem; border-left: 2px solid #ddd; }
pre, code { font-family: ui-monospace, monospace; }
pre { white-space: pre-wrap; overflow-wrap: anywhere; background: #f0efe9; padding: .5rem; }
.more { display: inline-block; margin: 1rem 0; }
footer { border-top: 1px solid #ccc; margin-top: 2rem; padding: 1rem 0; color: #555; font-size: .85rem; }

.x { content: "oops"; }

